def fill_codigo_fipe(apps, schema_editor):
    """Preenche VehicleModel.codigo_fipe nas linhas legadas antes da unicidade (tipo, codigo)."""
    VehicleModel = apps.get_model("vehicle_catalog", "VehicleModel")
    used: set[tuple[str, str]] = set()
    for modelo in VehicleModel.objects.order_by("pk"):
        version = modelo.versoes.exclude(codigo_fipe="").order_by("pk").first()
        codigo = version.codigo_fipe if version else ""
        # O código da versão cabe em 20; o do modelo, em 10. Repetido ou longo cai no fallback.
        if not codigo or len(codigo) > 10 or (modelo.tipo, codigo) in used:
            codigo = f"L{modelo.pk}"
        used.add((modelo.tipo, codigo))
        modelo.codigo_fipe = codigo
        modelo.save(update_fields=["codigo_fipe"])


